<script setup lang="ts">
import { computed, onMounted, reactive, ref } from 'vue'
import { actualizarEstado, guardarMaestro, listarEstados, type EstadoLogistico } from '../services/estados'
const rows=ref<EstadoLogistico[]>([]),catalogs=ref<Record<string,Record<string,string>>>({}),concepts=ref<Record<string,string>>({}),summary=ref<Record<string,number>>({}),concept=ref(''),value=ref(''),page=ref(1),lastPage=ref(1),total=ref(0),loading=ref(false),saving=ref(false),error=ref(''),success=ref(''),modal=ref(false),editing=ref<number|null>(null)
const form=reactive({concepto:0,codigo:'',descripcion:'',serie:'',cta_33_34:undefined as number|undefined,cta_39:undefined as number|undefined,cta_68:undefined as number|undefined,cta_39_rev:undefined as number|undefined,cta_68_rev:undefined as number|undefined,activo:true})
const isMaster=computed(()=>concept.value==='5'),regulatory=computed(()=>form.concepto===5)
async function load(next=1){page.value=next;loading.value=true;error.value='';try{const r=await listarEstados(concept.value,value.value,next);rows.value=r.data;catalogs.value=r.catalogos;concepts.value=r.conceptos;summary.value=r.resumen;total.value=r.total;lastPage.value=r.last_page}catch(e){error.value=message(e)}finally{loading.value=false}}
function states(row:EstadoLogistico){return catalogs.value[row.tipo]||{}}
async function change(row:EstadoLogistico,event:Event){const old=row.estado,next=(event.target as HTMLSelectElement).value;if(!confirm(`¿Cambiar el estado de ${row.tipo} #${row.id}?`)){(event.target as HTMLSelectElement).value=String(old);return}try{await actualizarEstado(row.tipo,row.id,next);row.estado=next;success.value='Estado actualizado correctamente.'}catch(e){error.value=message(e);(event.target as HTMLSelectElement).value=String(old)}}
function open(item?:EstadoLogistico){editing.value=item?.id||null;Object.assign(form,{concepto:item?.tabla_id||0,codigo:item?.codigo||'',descripcion:item?.referencia||'',serie:item?.serie||'',cta_33_34:item?.cta_33_34,cta_39:item?.cta_39,cta_68:item?.cta_68,cta_39_rev:item?.cta_39_rev,cta_68_rev:item?.cta_68_rev,activo:item?.activo??true});modal.value=true}
function validate(){if(!form.concepto)return 'Seleccione el concepto de tabla maestra.';if(!form.codigo.trim())return 'El código es obligatorio.';if(!form.descripcion.trim())return 'La descripción es obligatoria.';return ''}
async function save(){const issue=validate();if(issue){error.value=issue;return}saving.value=true;try{await guardarMaestro(editing.value,{...form});modal.value=false;success.value='Código de tabla maestra guardado correctamente.';await load(page.value)}catch(e){error.value=message(e)}finally{saving.value=false}}
const message=(e:unknown)=>e instanceof Error?e.message:'No se pudo completar la operación.';onMounted(()=>load())
</script>
<template><div class="page"><nav><RouterLink to="/inicio">Inicio</RouterLink> / Administración / Logística / Estados</nav><header class="hero"><div class="mark">ES</div><div><small>MIA · SUPERVISIÓN</small><h1>Estados logísticos</h1><p>Consulta y administra estados del ciclo de abastecimiento.</p></div><button v-if="isMaster" @click="open()">+ Código maestro</button></header><p v-if="success" class="flash success">✓ {{success}}</p><p v-if="error" class="flash">{{error}}</p><section class="metrics"><article v-for="(count,key) in summary" :key="key"><small>{{String(key).toUpperCase()}}</small><b>{{count}}</b></article></section><section class="filters"><label>Concepto<select v-model="concept"><option value="">Todos</option><option value="1">Pedidos</option><option value="2">Procesos</option><option value="3">Evaluaciones</option><option value="4">Órdenes</option><option value="5">Tabla maestra</option></select></label><label>Valor / ID<input v-model.trim="value" placeholder="Identificador exacto" @keyup.enter="load(1)"></label><button @click="load(1)">Consultar</button><button class="soft" @click="concept='';value='';load(1)">Limpiar</button></section>
<section class="table-card"><header><div><small>RESULTADOS</small><h2>{{isMaster?'Códigos de tabla maestra':'Entidades y estados actuales'}}</h2></div><b>{{total}} registros</b></header><div v-if="loading" class="empty">Consultando estados…</div><div v-else-if="!rows.length" class="empty">No se encontraron registros.</div><div v-else class="scroll"><table><thead><tr><th>Concepto</th><th>ID / Código</th><th>Descripción</th><th>Estado</th><th></th></tr></thead><tbody><tr v-for="row in rows" :key="row.uid"><td><span class="type">{{row.tipo.replaceAll('_',' ')}}</span></td><td><b>{{row.codigo||`#${row.id}`}}</b></td><td>{{row.referencia||'—'}}</td><td><span v-if="row.tipo==='tabla_maestra'" :class="row.activo?'active':'inactive'">{{row.activo?'ACTIVO':'INACTIVO'}}</span><select v-else :value="row.estado" @change="change(row,$event)"><option v-for="(name,id) in states(row)" :key="id" :value="id">{{name}}</option></select></td><td><button v-if="row.tipo==='tabla_maestra'" class="link" @click="open(row)">Editar</button></td></tr></tbody></table></div><footer v-if="lastPage>1"><button :disabled="page<=1" @click="load(page-1)">Anterior</button><span>{{page}} / {{lastPage}}</span><button :disabled="page>=lastPage" @click="load(page+1)">Siguiente</button></footer></section>
<div v-if="modal" class="backdrop" @mousedown.self="modal=false"><form class="dialog" @submit.prevent="save"><header><div><small>TABLA MAESTRA</small><h2>{{editing?'Editar':'Crear'}} código</h2></div><button type="button" @click="modal=false">×</button></header><div class="grid"><label>Concepto *<select v-model.number="form.concepto"><option :value="0">Seleccione</option><option v-for="(name,id) in concepts" :key="id" :value="Number(id)">{{name}}</option></select></label><label>Código *<input v-model.trim="form.codigo" maxlength="255"></label><label class="wide">Descripción *<input v-model.trim="form.descripcion" maxlength="255"></label><label>Serie<input v-model.trim="form.serie" maxlength="255"></label></div><section v-if="regulatory" class="accounts"><h3>Cuentas de clasificación regulatoria</h3><label>Cuenta 33/34<input v-model.number="form.cta_33_34" type="number"></label><label>Cuenta 39<input v-model.number="form.cta_39" type="number"></label><label>Cuenta 68<input v-model.number="form.cta_68" type="number"></label><label>Cuenta 39 reversión<input v-model.number="form.cta_39_rev" type="number"></label><label>Cuenta 68 reversión<input v-model.number="form.cta_68_rev" type="number"></label><label class="check"><input v-model="form.activo" type="checkbox"> Activo</label></section><footer><button type="button" class="soft" @click="modal=false">Cancelar</button><button :disabled="saving">{{saving?'Guardando…':'Guardar código'}}</button></footer></form></div></div></template>
<style scoped>
.page{--accent:#d64f83;color:#35464e}nav{margin-bottom:16px;color:#929fa5;font-size:.68rem}nav a{color:var(--accent);text-decoration:none}.hero{padding:20px 23px;display:flex;align-items:center;gap:14px;border-left:5px solid var(--accent);border-radius:12px;background:#fff}.mark{width:50px;height:50px;display:grid;place-items:center;border-radius:10px;color:#fff;background:var(--accent);font-size:.65rem;font-weight:700}.hero small,.metrics small,.table-card small,.dialog small{color:var(--accent);font-size:.49rem;font-weight:800}.hero h1{margin:2px 0;font-size:1.3rem}.hero p{margin:0;color:#7e8a90;font-size:.67rem}.hero button,.filters button,.table-card footer button,.dialog button{padding:8px 11px;border:0;border-radius:6px;color:#fff;background:var(--accent);font-size:.53rem}.hero button{margin-left:auto}.flash{padding:9px;border-radius:7px;color:#a64046;background:#fff0f0;font-size:.6rem}.flash.success{color:#287052;background:#edf9f3}.metrics{margin-top:11px;display:grid;grid-template-columns:repeat(5,1fr);gap:7px}.metrics article{padding:11px;border-radius:8px;background:#fff}.metrics b{display:block;margin-top:3px;font-size:.8rem}.filters{margin-top:10px;padding:11px;display:grid;grid-template-columns:1fr 1fr auto auto;align-items:end;gap:6px;border-radius:9px;background:#fff}label{font-size:.52rem}input,select{width:100%;box-sizing:border-box;margin-top:4px;padding:8px;border:1px solid #d9e0e3;border-radius:6px;font:inherit;font-size:.55rem}.soft{color:#64727a!important;background:#edf1f3!important}.table-card{margin-top:11px;border-radius:10px;background:#fff;overflow:hidden}.table-card>header{padding:13px 15px;display:flex;align-items:center;border-bottom:1px solid #e7ebed}.table-card h2{margin:2px 0;font-size:.75rem}.table-card>header>b{margin-left:auto;font-size:.54rem}.scroll{overflow:auto}table{width:100%;border-collapse:collapse;font-size:.52rem}th,td{padding:9px;border-bottom:1px solid #e8ecee;text-align:left}th{color:#fff;background:#5b6e8e}.type,.active,.inactive{padding:4px 6px;border-radius:8px;color:#456675;background:#eaf2f5;font-size:.44rem}.active{color:#287154;background:#e6f7ee}.inactive{color:#9d4046;background:#fdebed}.link{border:0;color:var(--accent);background:none}.empty{padding:45px;text-align:center;font-size:.6rem}.table-card>footer{padding:10px;display:flex;justify-content:center;align-items:center;gap:8px;font-size:.52rem}.backdrop{position:fixed;z-index:100;inset:0;padding:20px;display:grid;place-items:center;background:#172b3d88}.dialog{width:min(750px,100%);padding:20px;box-sizing:border-box;border-radius:12px;background:#fff}.dialog>header{display:flex}.dialog h2{margin:2px 0 13px;font-size:1rem}.dialog>header button{margin-left:auto;color:#59666c;background:none;font-size:1.2rem}.grid,.accounts{display:grid;grid-template-columns:1fr 1fr;gap:8px}.wide,.accounts h3{grid-column:1/-1}.accounts{margin:12px 0;padding:11px;border-radius:8px;background:#f5f7f8}.accounts h3{margin:0;font-size:.58rem}.check{display:flex;align-items:center;gap:6px}.check input{width:auto}.dialog>footer{margin-top:12px;display:flex;justify-content:flex-end;gap:6px}@media(max-width:850px){.metrics{grid-template-columns:1fr 1fr}.filters,.grid,.accounts{grid-template-columns:1fr}.wide,.accounts h3{grid-column:auto}}
</style>
